12	
13	// 本文件保护“打开本地数据”时对样品采样点归属的核对：每份样品的 pointId
14	// 必须完整（字段缺失、为 null、为空字符串或仅含空白都算缺少采样点编号），
15	// 不含首尾空白，且按 JSON 解码后的文本与本文件已登记的采样点编号逐字匹配
16	// （不转大小写；Unicode 转义表示同一文本可以匹配）。编号完整但没有对应登记
17	// 记录时，必须明确报该采样点未登记，不能凭限值记录或其他样品推测它存在。
18	// 核对适用于待判定、已确认和已作废样品；只要一份样品不符合要求，整次 Open
19	// 失败、返回 nil 存放、错误可识别为 ErrCorruptRecord，信息点到样品编号并
20	// 区分三种问题，含首尾空白与未登记时带出原采样点编号；其他样品正常也不能
21	// 只读入正常部分，原文件字节不变。
22	
23	// pointCheckSample 构造一份除采样点归属外内容完整的样品，便于证明测量与
24	// 判定依据完整不能代替采样点已经登记。confirmed 带完整达标判定，voided
25	// 带作废原因（待判定后直接作废、无历史依据）。
26	func pointCheckSample(id, pointID string, status Status) *Sample {
27		smp := &Sample{
28			ID:           id,
29			PointID:      pointID,
30			SampledAt:    at(10, 0),
31			Measurements: []Measurement{{Item: openPH, Value: 7}},
32			Status:       status,
33		}
34		switch status {
35		case StatusConfirmed:
36			smp.Exceeded = false
37			smp.Results = []ItemResult{
38				{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
39			}
40		case StatusVoided:
41			smp.VoidReason = "录入信息有误"
42		}
43		return smp
44	}
45	
46	// sampleJSONWithPointToken 把样品序列化结果中的 "pointId":"..." 字段整体
47	// 替换成 pointToken 给出的原始 JSON 片段；空串表示整个字段缺失。
48	func sampleJSONWithPointToken(t *testing.T, smp *Sample, pointToken string) string {
49		t.Helper()
50		b, err := json.Marshal(smp)
51		if err != nil {
52			t.Fatalf("marshal sample: %v", err)
53		}
54		s := string(b)
55		if pointToken == "" {
56			old := `,"pointId":"` + smp.PointID + `"`
57			if !strings.Contains(s, old) {
58				t.Fatalf("序列化结果中找不到采样点字段 %q：%s", old, s)
59			}
60			return strings.Replace(s, old, "", 1)
61		}
62		old := `"pointId":"` + smp.PointID + `"`
63		if !strings.Contains(s, old) {
64			t.Fatalf("序列化结果中找不到采样点字段 %q：%s", old, s)
65		}
66		return strings.Replace(s, old, pointToken, 1)
67	}
68	
69	// assertOpenPointCorrupt 打开并断言：整次失败、nil 存放、ErrCorruptRecord，
70	// 去掉哨兵前缀后的具体原因包含所有 want 子串、且不包含任一 notWant 子串，
71	// 原文件字节不变。
72	func assertOpenPointCorrupt(t *testing.T, dir string, want, notWant []string) {
73		t.Helper()
74		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
75		if err != nil {
76			t.Fatalf("read file before open: %v", err)
77		}
78		got, err := Open(dir)
79		if err == nil {
80			if got != nil {
81				got.Close()
82			}
83			t.Fatalf("归属有问题的样品必须让整次 Open 失败")
84		}
85		if got != nil {
86			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
87		}
88		if !errors.Is(err, ErrCorruptRecord) {
89			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
90		}
91		detail := strings.TrimPrefix(err.Error(), ErrCorruptRecord.Error())
92		for _, w := range want {
93			if !strings.Contains(detail, w) {
94				t.Fatalf("具体错误原因应包含 %q，实际 %q", w, detail)
95			}
96		}
97		for _, nw := range notWant {
98			if strings.Contains(detail, nw) {
99				t.Fatalf("具体错误原因不应包含 %q，实际 %q", nw, detail)
100			}
101		}
102		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
103		if rerr != nil {
104			t.Fatalf("read file after open: %v", rerr)
105		}
106		if string(after) != string(before) {
107			t.Fatalf("打开失败不得覆盖或改写原数据文件")
108		}
109	}
110	
111	// 任务中的核心场景：文件只登记了 P1，已确认样品 S1 的 pointId 却写着 P9，
112	// 其余内容（测量、判定依据、超标标记）完整也必须整次拒绝；否则它甚至能作为
113	// P9 的最近有效结果返回。
114	func TestOpenConfirmedSampleBelongsToUnregisteredPoint(t *testing.T) {
115		dir := t.TempDir()
116		writeDiskFile(t, dir, diskState{
117			Points: openPoints(),
118			Samples: map[string]*Sample{
119				"S1": pointCheckSample("S1", "P9", StatusConfirmed),
120			},
121		})
122		assertOpenPointCorrupt(t, dir,
123			[]string{"S1", "P9", "未登记"},
124			[]string{"缺少采样点编号", "含首尾空白"})
125	
126		// 打开失败返回 nil 存放：P9 不可能通过任何查询拿到这份“最近有效结果”。
127		s, err := Open(dir)
128		if err == nil {
129			s.Close()
130			t.Fatalf("归属不明的记录仍在文件中时打开必须持续失败")
131		}
132	}
133	
134	// 归属核对适用于待判定、已确认和已作废三种状态；作废记录仍供按点核对，
135	// 已确认样品的判定依据完整也不能代替采样点已经登记。
136	func TestOpenUnknownPointAppliesToAllStatuses(t *testing.T) {
137		cases := []struct {
138			name   string
139			status Status
140		}{
141			{"待判定", StatusPending},
142			{"已确认", StatusConfirmed},
143			{"已作废", StatusVoided},
144		}
145		for _, c := range cases {
146			t.Run(c.name, func(t *testing.T) {
147				dir := t.TempDir()
148				writeDiskFile(t, dir, diskState{
149					Points: openPoints(),
150					Samples: map[string]*Sample{
151						"S1": pointCheckSample("S1", "P9", c.status),
152					},
153				})
154				assertOpenPointCorrupt(t, dir, []string{"S1", "P9", "未登记"}, nil)
155			})
156		}
157	}
158	
159	// pointId 字段的各种缺失写法都算缺少采样点编号：字段缺失、null、空字符串、
160	// 仅含空白；后两种通过 Go 结构体也能构造，前两种必须用原始 JSON。
161	func TestOpenMissingPointIDForms(t *testing.T) {
162		cases := []struct {
163			name    string
164			raw     bool // true 时用原始 JSON 片段构造
165			token   string
166			struct_ string // raw=false 时结构体直接使用的 pointId
167		}{
168			{"字段缺失", true, "", ""},
169			{"null", true, `"pointId":null`, ""},
170			{"空字符串", false, "", ""},
171			{"仅含空格", false, "", "   "},
172			{"仅含制表与换行", false, "", "\t\n "},
173		}
174		for _, c := range cases {
175			t.Run(c.name, func(t *testing.T) {
176				dir := t.TempDir()
177				if c.raw {
178					obj := sampleJSONWithPointToken(t, pointCheckSample("S1", "P1", StatusPending), c.token)
179					writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
180						rawEntryWithObject(`"S1"`, obj),
181					}))
182				} else {
183					writeDiskFile(t, dir, diskState{
184						Points: openPoints(),
185						Samples: map[string]*Sample{
186							"S1": pointCheckSample("S1", c.struct_, StatusPending),
187						},
188					})
189				}
190				assertOpenPointCorrupt(t, dir,
191					[]string{"S1", "缺少采样点编号"},
192					[]string{"未登记", "含首尾空白"})
193			})
194		}
195	}
196	
197	// 带首尾空白的编号属于损坏：即使去掉空白后正好是已登记的 P1，也不能替它
198	// 找到采样点；错误信息带出原采样点编号。
199	func TestOpenPointIDWithSurroundingWhitespaceRejected(t *testing.T) {
200		cases := []struct {
201			name    string
202			pointID string
203		}{
204			{"首尾空格", " P1 "},
205			{"仅前导制表", "\tP1"},
206			{"仅末尾换行", "P1\n"},
207			{"空白但去空白后非空", "  P1  "},
208		}
209		for _, c := range cases {
210			t.Run(c.name, func(t *testing.T) {
211				dir := t.TempDir()
212				writeDiskFile(t, dir, diskState{
213					Points: openPoints(),
214					Samples: map[string]*Sample{
215						"S1": pointCheckSample("S1", c.pointID, StatusPending),
216					},
217				})
218				assertOpenPointCorrupt(t, dir,
219					[]string{"S1", "含首尾空白", strconv.Quote(c.pointID)},
220					[]string{"未登记", "缺少采样点编号"})
221			})
222		}
223	}
224	
225	// 编号按 JSON 解码后的文本逐字匹配、不转换大小写：P1 已登记，样品写 p1
226	// 时按采样点未登记拒绝，错误带出原编号 p1。
227	func TestOpenPointIDComparisonIsCaseSensitive(t *testing.T) {
228		dir := t.TempDir()
229		writeDiskFile(t, dir, diskState{
230			Points: openPoints(),
231			Samples: map[string]*Sample{
232				"S1": pointCheckSample("S1", "p1", StatusConfirmed),
233			},
234		})
235		assertOpenPointCorrupt(t, dir,
236			[]string{"S1", strconv.Quote("p1"), "未登记"},
237			[]string{"含首尾空白", "缺少采样点编号"})
238	}
239	
240	// Unicode 转义只是 JSON 的另一种写法：pointId 用 P1 表示 P1，解码后
241	// 与已登记编号是同一文本，必须正常读入；中文编号与其 Unicode 转义同理。
242	func TestOpenPointIDUnicodeEscapeSameTextAccepted(t *testing.T) {
243		t.Run("P1转义", func(t *testing.T) {
244			dir := t.TempDir()
245			// 文件里真的出现 \u00501 这样的六个转义字符（P = U+0050），JSON
246			// 解码后是 P1，与已登记编号是同一文本。
247			obj := sampleJSONWithPointToken(t, pointCheckSample("S1", "P1", StatusPending),
248				"\"pointId\":\"\\u00501\"")
249			writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
250				rawEntryWithObject(`"S1"`, obj),
251			}))
252			s, err := Open(dir)
253			if err != nil {
254				t.Fatalf("Unicode 转义表示同一已登记编号时应正常读入: %v", err)
255			}
256			defer s.Close()
257			list, err := s.ListByPoint("P1")
258			if err != nil || len(list) != 1 || list[0].PointID != "P1" {
259				t.Fatalf("样品应归属已登记的 P1: %+v err=%v", list, err)
260			}
261		})
262	
263		t.Run("中文编号转义", func(t *testing.T) {
264			dir := t.TempDir()
265			pts := map[string]SamplingPoint{
266				"P1": {ID: "P1", Name: "一号取水口"},
267				"一号": {ID: "一号", Name: "中文采样点"},
268			}
269			// 一 = U+4E00，号 = U+53F7：转义写法解码后与已登记的“一号”逐字相同。
270			obj := sampleJSONWithPointToken(t, pointCheckSample("S1", "一号", StatusPending),
271				"\"pointId\":\"\\u4e00\\u53f7\"")
272			ptsJSON, err := json.Marshal(pts)
273			if err != nil {
274				t.Fatalf("marshal points: %v", err)
275			}
276			writeRawDataFile(t, dir, `{"points":`+string(ptsJSON)+`,"samples":{`+
277				`"S1":`+obj+`}}`)
278			s, err := Open(dir)
279			if err != nil {
280				t.Fatalf("中文编号的 Unicode 转义应与已登记编号匹配: %v", err)
281			}
282			defer s.Close()
283			if list, err := s.ListByPoint("一号"); err != nil || len(list) != 1 {
284				t.Fatalf("样品应归属中文编号采样点: %+v err=%v", list, err)
285			}
286		})
287	}
288	
289	// 编号内部的合法字符仍可使用：注册并引用 "P 1" 是正常数据。
290	func TestOpenPointIDInternalWhitespaceAccepted(t *testing.T) {
291		dir := t.TempDir()
292		writeDiskFile(t, dir, diskState{
293			Points: map[string]SamplingPoint{"P 1": {ID: "P 1", Name: "内部空白采样点"}},
294			Samples: map[string]*Sample{
295				"S1": pointCheckSample("S1", "P 1", StatusPending),
296			},
297		})
298		s, err := Open(dir)
299		if err != nil {
300			t.Fatalf("编号内部空白是合法文本，应正常读入: %v", err)
301		}
302		defer s.Close()
303		if list, err := s.ListByPoint("P 1"); err != nil || len(list) != 1 {
304			t.Fatalf("样品应归属 P 1: %+v err=%v", list, err)
305		}
306	}
307	
308	// 不能凭限值记录推测采样点存在：文件中存在归属 P9 的限值，但 points 没有
309	// P9 时，pointId 为 P9 的样品仍按采样点未登记拒绝。
310	func TestOpenUnregisteredPointNotInferredFromLimits(t *testing.T) {
311		dir := t.TempDir()
312		writeDiskFile(t, dir, diskState{
313			Points: openPoints(),
314			Limits: map[string][]Limit{
315				diskLimitKey("P9", openPH): {
316					{PointID: "P9", Item: openPH, Value: 8, Effective: openEff()},
317				},
318			},
319			Samples: map[string]*Sample{
320				"S1": pointCheckSample("S1", "P9", StatusPending),
321			},
322		})
323		assertOpenPointCorrupt(t, dir, []string{"S1", "P9", "未登记"}, nil)
324	}
325	
326	// 不能凭其他样品推测采样点存在：两份样品都写 P9 不能让 P9 变成已登记。
327	func TestOpenUnregisteredPointNotInferredFromOtherSamples(t *testing.T) {
328		dir := t.TempDir()
329		writeDiskFile(t, dir, diskState{
330			Points: openPoints(),
331			Samples: map[string]*Sample{
332				"S1": pointCheckSample("S1", "P9", StatusPending),
333				"S2": pointCheckSample("S2", "P9", StatusConfirmed),
334			},
335		})
336		assertOpenPointCorrupt(t, dir, []string{"未登记", "P9"}, nil)
337	}
338	
339	// 归属核对先于状态等其他逐份检查：pointId 缺失时即使 status 也缺失，也必须
340	// 先报缺少采样点编号；pointId 含空白时即使状态非法，也必须先报含首尾空白。
341	func TestOpenPointCheckReportedBeforeOtherDamage(t *testing.T) {
342		t.Run("缺少编号先于缺状态", func(t *testing.T) {
343			dir := t.TempDir()
344			obj := sampleJSONWithPointToken(t, pointCheckSample("S1", "P1", StatusPending), "")
345			obj = strings.Replace(obj, `,"status":"pending"`, "", 1)
346			writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
347				rawEntryWithObject(`"S1"`, obj),
348			}))
349			assertOpenPointCorrupt(t, dir,
350				[]string{"S1", "缺少采样点编号"},
351				[]string{"缺少状态"})
352		})
353	
354		t.Run("含空白先于非法状态", func(t *testing.T) {
355			dir := t.TempDir()
356			smp := pointCheckSample("S1", " P1 ", StatusPending)
357			b, err := json.Marshal(smp)
358			if err != nil {
359				t.Fatalf("marshal: %v", err)
360			}
361			obj := strings.Replace(string(b), `"status":"pending"`, `"status":"bogus"`, 1)
362			writeRawDataFile(t, dir, rawStoreWithEntries(t, []string{
363				rawEntryWithObject(`"S1"`, obj),
364			}))
365			assertOpenPointCorrupt(t, dir,
366				[]string{"S1", "含首尾空白"},
367				[]string{"bogus"})
368		})
369	}
370	
371	// 同文件其他样品正常也不能只读入正常部分：一份归属不明的样品让整次打开失败；
372	// 修复文件后正常样品的状态与结论原样可读。失败的打开不回写原文件。
373	func TestOpenPointProblemRejectsWholeFile(t *testing.T) {
374		dir := t.TempDir()
375		good := &Sample{
376			ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
377			Measurements: []Measurement{{Item: openPH, Value: 7}},
378			Status:       StatusConfirmed, Exceeded: false,
379			Results: []ItemResult{
380				{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
381			},
382		}
383		bad := pointCheckSample("S-BAD", "P9", StatusConfirmed)
384		writeDiskFile(t, dir, diskState{
385			Points:  openPoints(),
386			Samples: map[string]*Sample{"S-GOOD": good, "S-BAD": bad},
387		})
388		assertOpenPointCorrupt(t, dir, []string{"S-BAD", "P9", "未登记"}, nil)
389	
390		// 移除归属不明的记录后，正常样品原样可读：证明失败时没有部分读入或改写。
391		writeDiskFile(t, dir, diskState{
392			Points:  openPoints(),
393			Samples: map[string]*Sample{"S-GOOD": good},
394		})
395		s, err := Open(dir)
396		if err != nil {
397			t.Fatalf("移除归属不明记录后应正常打开: %v", err)
398		}
399		defer s.Close()
400		latest, ok, err := s.LatestResult("P1")
401		if err != nil || !ok || latest.ID != "S-GOOD" {
402			t.Fatalf("最近有效结果应指向未被改动的正常样品: %+v ok=%v err=%v", latest, ok, err)
403		}
404	}
405	
406	// 失败时不补登记采样点、不改写样品归属：同一份损坏文件重复打开仍失败，
407	// 且文件字节与首次打开前完全一致。
408	func TestOpenPointFailureDoesNotMutateFile(t *testing.T) {
409		dir := t.TempDir()
410		writeDiskFile(t, dir, diskState{
411			Points: openPoints(),
412			Samples: map[string]*Sample{
413				"S1": pointCheckSample("S1", "P9", StatusPending),
414			},
415		})
416		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
417		if err != nil {
418			t.Fatalf("read before: %v", err)
419		}
420		for i := 0; i < 2; i++ {
421			if got, err := Open(dir); err == nil {
422				got.Close()
423				t.Fatalf("第 %d 次打开仍应失败", i+1)
424			}
425		}
426		after, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
427		if err != nil {
428			t.Fatalf("read after: %v", err)
429		}
430		if string(after) != string(before) {
431			t.Fatalf("重复失败的打开不得补登记采样点或改写归属")
432		}
433	}
434	
435	// 采样点已登记但尚未登记限值的待判定样品仍可打开；是否缺少采样当时适用的
436	// 上限继续由确认操作判断（ErrMissingLimit）。
437	func TestOpenPendingSampleWithoutLimitsStillOpens(t *testing.T) {
438		dir := t.TempDir()
439		writeDiskFile(t, dir, diskState{
440			Points: openPoints(),
441			Samples: map[string]*Sample{
442				"S1": pointCheckSample("S1", "P1", StatusPending),
443			},
444		})
445		s, err := Open(dir)
446		if err != nil {
447			t.Fatalf("采样点已登记、限值未登记的待判定样品应正常打开: %v", err)
448		}
449		defer s.Close()
450		list, err := s.ListByPoint("P1")
451		if err != nil || len(list) != 1 || list[0].Status != StatusPending {
452			t.Fatalf("待判定样品应原样读入: %+v err=%v", list, err)
453		}
454		if _, err := s.Confirm("S1"); !errors.Is(err, ErrMissingLimit) {
455			t.Fatalf("缺少适用上限仍应由确认操作判断，got %v", err)
456		}
457	}
458	
459	// 正常流程保存的数据（含录入、确认、作废、重开）归属始终完整，读入后状态、
460	// 测量、历史判定依据、按点列表与最近有效结果的排序和作废资格保持不变。
461	func TestOpenNormalFlowUnchangedAfterPointCheck(t *testing.T) {
462		s, dir := open(t)
463		mustPoint(t, s, "P1", "一号取水口")
464		mustPoint(t, s, "P2", "二号取水口")
465		mustLimit(t, s, "P1", openPH, 8, openEff())
466		mustLimit(t, s, "P2", openPH, 8, openEff())
467		mustSample(t, s, "S1", "P1", at(2, 0), Measurement{Item: openPH, Value: 7}) // 早、待判定后作废
468		mustSample(t, s, "S2", "P2", at(3, 0), Measurement{Item: openPH, Value: 9}) // 已确认超标
469		if _, err := s.Confirm("S2"); err != nil {
470			t.Fatalf("Confirm S2: %v", err)
471		}
472		if _, err := s.Void("S1", "录入信息有误"); err != nil {
473			t.Fatalf("Void S1: %v", err)
474		}
475		if err := s.Close(); err != nil {
476			t.Fatalf("Close: %v", err)
477		}
478	
479		s2, err := Open(dir)
480		if err != nil {
481			t.Fatalf("正常保存的文件应照常打开: %v", err)
482		}
483		defer s2.Close()
484	
485		p1, err := s2.ListByPoint("P1")
486		if err != nil || len(p1) != 1 || p1[0].ID != "S1" || p1[0].Status != StatusVoided {
487			t.Fatalf("P1 的作废记录应原样保留: %+v err=%v", p1, err)
488		}
489		if latest, ok, err := s2.LatestResult("P1"); err != nil || ok {
490			t.Fatalf("P1 应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
491		}
492		latest, ok, err := s2.LatestResult("P2")
493		if err != nil || !ok || latest.ID != "S2" || !latest.Exceeded {
494			t.Fatalf("P2 最近有效结果应保留 S2 的超标结论: %+v ok=%v err=%v", latest, ok, err)
495		}
496		if r := latest.Results[0]; r.Limit != 8 || !r.LimitEffective.Equal(openEff()) || !r.Exceeded {
497			t.Fatalf("历史判定依据必须原样保留: %+v", r)
498		}
499		if _, err := s2.Confirm("S1"); !errors.Is(err, ErrVoided) {
500			t.Fatalf("作废资格应保持不变，got %v", err)
501		}
502	}
503	
504	// 没有样品的空目录、样品集合为空或缺失的已有数据都照常打开，不要求存在样品
505	// 归属。
506	func TestOpenEmptyDataStillOpensAfterPointCheck(t *testing.T) {
507		dir := t.TempDir()
508		s, err := Open(dir)
509		if err != nil {
510			t.Fatalf("全新空目录应照常打开: %v", err)
511		}
512		s.Close()
513	
514		writeDiskFile(t, dir, diskState{Points: openPoints(), Samples: map[string]*Sample{}})
515		s2, err := Open(dir)
516		if err != nil {
517			t.Fatalf("空样品集合应照常打开: %v", err)
518		}
519		s2.Close()
520	
521		writeRawDataFile(t, dir, `{"points": {"P1": {"id": "P1", "name": "一号取水口"}}}`)
522		s3, err := Open(dir)
523		if err != nil {
524			t.Fatalf("样品集合缺失应照常打开: %v", err)
525		}
526		s3.Close()
527	}
