3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 本文件保护“打开本地数据”时对登记限值上限数值的完整性核对：
14	// 文件中实际存在的每一版登记限值都必须实际保存上限数值，value 字段缺失或
15	// 保存为 null 都是限值记录残缺——JSON 反序列化会把它们落成零，与明确保存的
16	// 零上限无法区分，只能按字段是否存在核对。整次 Open 失败、返回 nil 存放、
17	// 错误可识别为 ErrCorruptRecord 并点到该限值自身的采样点编号、项目与生效
18	// 时间，明确说明缺少上限数值；不补成零、不跳过这一版、不借用同项目另一版
19	// 的数值、不改写原文件，也不把拒绝推迟到确认某份样品时。这条核对与当前有
20	// 没有样品、这一版是否已被样品采用无关：旧版或尚未生效的版本缺少数值同样
21	// 拒绝，文件尚未录入任何样品时也一样。明确保存的数值零仍是合法上限，负数
22	// 和正数保持现有含义；没有登记限值的空数据照常打开。
23	
24	// assertOpenRejectsLimitValue 断言打开因某版登记限值缺少上限数值而整次失败：
25	// 返回 nil 存放、错误可识别为 ErrCorruptRecord，信息点到该限值自身的采样点
26	// 编号、项目与生效时间并说明缺少上限数值，原文件字节不被改动。
27	func assertOpenRejectsLimitValue(t *testing.T, dir, point, item string, eff time.Time) {
28		t.Helper()
29		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
30		if err != nil {
31			t.Fatalf("read file before open: %v", err)
32		}
33		got, err := Open(dir)
34		if err == nil {
35			if got != nil {
36				got.Close()
37			}
38			t.Fatalf("缺少上限数值的限值必须让整次 Open 失败，%s/%s @ %s", point, item, eff)
39		}
40		if got != nil {
41			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
42		}
43		if !errors.Is(err, ErrCorruptRecord) {
44			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
45		}
46		msg := err.Error()
47		for _, want := range []string{point, item, eff.UTC().String(), "上限数值", "value"} {
48			if !strings.Contains(msg, want) {
49				t.Fatalf("错误信息应包含 %q（采样点、项目、生效时间与缺少上限数值的说明），实际 %q", want, msg)
50			}
51		}
52		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
53		if rerr != nil {
54			t.Fatalf("read file after open: %v", rerr)
55		}
56		if string(after) != string(before) {
57			t.Fatalf("打开失败不得覆盖或改写原数据文件")
58		}
59	}
60	
61	// 唯一一版限值的 value 字段整个缺失：读出的零不是合法上限，不能让它随后被
62	// 当成零上限参与判定，整次打开失败并点名该限值的采样点、项目与生效时间。
63	func TestOpenLimitMissingValueField(t *testing.T) {
64		dir := t.TempDir()
65		raw := `{
66	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
67	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH", "effective": "` +
68			openEff().Format(time.RFC3339Nano) + `"}]},
69	  "samples": {
70	    "S1": {
71	      "id": "S1", "pointId": "P1",
72	      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
73	      "measurements": [{"item": "pH", "value": 0}],
74	      "status": "pending"
75	    }
76	  }
77	}`
78		writeRawDiskFile(t, dir, raw)
79		assertOpenRejectsLimitValue(t, dir, "P1", openPH, openEff())
80	}
81	
82	// 限值的 value 保存为 null 与字段缺失一样是记录残缺：null 不是数值零。
83	func TestOpenLimitNullValue(t *testing.T) {
84		dir := t.TempDir()
85		raw := `{
86	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
87	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH", "value": null, "effective": "` +
88			openEff().Format(time.RFC3339Nano) + `"}]}
89	}`
90		writeRawDiskFile(t, dir, raw)
91		assertOpenRejectsLimitValue(t, dir, "P1", openPH, openEff())
92	}
93	
94	// 文件尚未录入任何样品时，缺少数值的限值同样让整次打开失败：
95	// 这条核对与有没有样品无关，不能等确认某份样品时才报告。
96	func TestOpenLimitMissingValueWithoutSamples(t *testing.T) {
97		dir := t.TempDir()
98		raw := `{
99	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
100	  "limits": {"P1-pH": [{"pointId": "P1", "item": "pH", "effective": "` +
101			openEff().Format(time.RFC3339Nano) + `"}]}
102	}`
103		writeRawDiskFile(t, dir, raw)
104		assertOpenRejectsLimitValue(t, dir, "P1", openPH, openEff())
105	}
106	
107	// 同一项目有多版限值，旧版缺少数值、最新版完整：不能只检查最新版本，
108	// 缺数值的旧版同样让整次打开失败，也不能借用另一版的数值补上。
109	func TestOpenOldLimitVersionMissingValue(t *testing.T) {
110		dir := t.TempDir()
111		raw := `{
112	  "points": {"P1": {"id": "P1", "name": "一号取水口"}},
113	  "limits": {"P1-pH": [
114	    {"pointId": "P1", "item": "pH", "effective": "` + at(1, 0).Format(time.RFC3339Nano) + `"},
115	    {"pointId": "P1", "item": "pH", "value": 8, "effective": "` + at(5, 0).Format(time.RFC3339Nano) + `"}
116	  ]},
117	  "samples": {
118	    "S1": {
119	      "id": "S1", "pointId": "P1",
120	      "sampledAt": "` + at(10, 0).Format(time.RFC3339Nano) + `",
121	      "measurements": [{"item": "pH", "value": 7}],
122	      "status": "pending"
