// 缺数值的限值与其他采样点、其他项目的完整限值以及完整样品同处一个文件：
// 不能只跳过问题版本继续打开，整次失败、无可用存放，其余数据也读不到。
func TestOpenLimitMissingValueRejectsWholeFile(t *testing.T) {
