1	package water
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// 本文件保护“打开本地数据”时对限值版本唯一性的核对：
13	// 同一采样点、同一项目下，只要存在两条生效时刻相同的上限，整次 Open 就必须失败，
14	// 返回 nil 存放，错误可被 errors.Is(err, ErrDuplicateLimitTime) 识别，并点到具体
15	// 采样点、项目与重复的生效时间。即使两条数值完全相同也算重复：不合并、不择一、
16	// 不跳过问题组只读入其余部分；其他采样点与样品再正常也不部分读入；原文件不被
17	// 改写；拒绝发生在打开时，不推迟到确认某份样品。
18	//
19	// 归属只由每条记录自身的采样点编号与项目名共同确定，不看落盘键：重复版本放在
20	// 同一存储条目或分散在不同条目里都要识别；共用旧版存储键的不同（采样点，项目）
21	// 组合沿用现有兼容行为，不误判成同一组。生效时刻按真实时刻判断：不同时区偏移
22	// 表示同一瞬间仍算重复，相差一纳秒是两版合法版本。没有重复的多版本数据可乱序
23	// 保存后正常打开，待判定样品确认时继续采用采样当时已生效的最近一版，恰好等于
24	// 生效时刻采用新版；已保存的历史判定依据原样保留，不因读取检查重算。
25	
26	// assertOpenRejectsDuplicateLimit 断言打开因限值生效时间重复而整次失败：
27	// 返回 nil 存放、错误为 ErrDuplicateLimitTime，信息点到采样点、项目与重复时刻，
28	// 原文件字节不变。
29	func assertOpenRejectsDuplicateLimit(t *testing.T, dir, point, item string, eff time.Time) {
30		t.Helper()
31		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
32		if err != nil {
33			t.Fatalf("read file before open: %v", err)
34		}
35		got, err := Open(dir)
36		if err == nil {
37			if got != nil {
38				got.Close()
39			}
40			t.Fatalf("同组同刻的重复上限必须让整次 Open 失败，%s/%s @ %s", point, item, eff)
41		}
42		if got != nil {
43			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
44		}
45		if !errors.Is(err, ErrDuplicateLimitTime) {
46			t.Fatalf("应返回 ErrDuplicateLimitTime，got %v", err)
47		}
48		msg := err.Error()
49		// 与 SetLimit 拒绝重复登记时一致，时间用 Go time.String() 形式（含小数秒，
50		// 保留纳秒精度），并统一到 UTC 表达。
51		for _, want := range []string{point, item, eff.UTC().String()} {
52			if !strings.Contains(msg, want) {
53				t.Fatalf("错误信息应包含 %q（采样点、项目与重复生效时间），实际 %q", want, msg)
54			}
55		}
56		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
57		if rerr != nil {
58			t.Fatalf("read file after open: %v", rerr)
59		}
60		if string(after) != string(before) {
61			t.Fatalf("打开失败不得覆盖或改写原数据文件")
62		}
63	}
64	
65	// 同一存储条目下，同一采样点同一项目的两条上限生效时刻相同，即使数值不同，
66	// 也必须在打开时整次拒绝；文件中另有正常采样点与待判定样品也不能部分读入。
67	func TestOpenDuplicateLimitSameEntryRejectsWholeFile(t *testing.T) {
68		dir := t.TempDir()
69		eff := at(5, 0)
70		writeDiskFile(t, dir, diskState{
71			Points: map[string]SamplingPoint{
72				"P1": {ID: "P1", Name: "一号取水口"},
73				"P2": {ID: "P2", Name: "二号取水口"},
74			},
75			Limits: map[string][]Limit{
76				diskLimitKey("P1", openPH): {
77					{PointID: "P1", Item: openPH, Value: 7, Effective: eff},
78					{PointID: "P1", Item: openPH, Value: 9, Effective: eff},
79				},
80				// 另一采样点的正常限值不能“稀释”问题组。
81				diskLimitKey("P2", openPH): {
82					{PointID: "P2", Item: openPH, Value: 8, Effective: at(1, 0)},
83				},
84			},
85			Samples: map[string]*Sample{
86				// 与重复限值无关的正常待判定样品，也不能被部分读入。
87				"S-OK": {
88					ID: "S-OK", PointID: "P2", SampledAt: at(6, 0),
89					Measurements: []Measurement{{Item: openPH, Value: 7}},
90					Status:       StatusPending,
91				},
92			},
93		})
94		assertOpenRejectsDuplicateLimit(t, dir, "P1", openPH, eff)
95	}
96	
97	// 两条上限连数值都完全相同，仍是重复版本：不能合并、不能当成同一条放行。
98	func TestOpenDuplicateLimitIdenticalRecords(t *testing.T) {
99		dir := t.TempDir()
100		eff := at(5, 0)
101		dup := Limit{PointID: "P1", Item: openPH, Value: 7, Effective: eff}
102		writeDiskFile(t, dir, diskState{
103			Points: openPoints(),
104			Limits: map[string][]Limit{
105				diskLimitKey("P1", openPH): {dup, dup},
106			},
107		})
108		assertOpenRejectsDuplicateLimit(t, dir, "P1", openPH, eff)
109	}
110	
111	// 同一生效时刻的两条版本分散在不同存储条目下，只看存储键就发现不了：
112	// 读取按每条记录自身的采样点与项目重新分组，仍必须识别为同一组重复。
113	func TestOpenDuplicateLimitSpreadAcrossStorageKeys(t *testing.T) {
114		dir := t.TempDir()
115		eff := at(5, 0)
116		writeDiskFile(t, dir, diskState{
117			Points: openPoints(),
118			Limits: map[string][]Limit{
119				"任意键-甲": {
120					{PointID: "P1", Item: openPH, Value: 7, Effective: eff},
121				},
122				"任意键-乙": {
123					{PointID: "P1", Item: openPH, Value: 9, Effective: eff},
124				},
125			},
126		})
127		assertOpenRejectsDuplicateLimit(t, dir, "P1", openPH, eff)
128	}
129	
130	// 不同时区偏移但表示同一瞬间的两个日期仍算重复：不能按时区字面值放行。
131	func TestOpenDuplicateLimitSameInstantDifferentZones(t *testing.T) {
132		dir := t.TempDir()
133		utc := time.Date(2026, 9, 5, 0, 0, 0, 500_000_000, time.UTC)
134		beijing := time.Date(2026, 9, 5, 8, 0, 0, 500_000_000, time.FixedZone("CST", 8*3600))
135		if !utc.Equal(beijing) {
136			t.Fatal("测试前提：两种时区写法应表示同一真实时刻")
137		}
138		writeDiskFile(t, dir, diskState{
139			Points: openPoints(),
140			Limits: map[string][]Limit{
141				diskLimitKey("P1", openPH): {
142					{PointID: "P1", Item: openPH, Value: 7, Effective: utc},
143					{PointID: "P1", Item: openPH, Value: 9, Effective: beijing},
144				},
145			},
146		})
147		assertOpenRejectsDuplicateLimit(t, dir, "P1", openPH, utc)
148	}
149	
150	// 相差一纳秒的两版生效时间是合法的不同版本，不能按秒截断后误报：
151	// 文件正常打开，边界前一纳秒用旧版、恰好生效用新版。
152	func TestOpenLimitsOneNanosecondApartAreDistinctVersions(t *testing.T) {
153		dir := t.TempDir()
154		boundary := time.Date(2026, 9, 10, 12, 0, 0, 500_000_000, time.UTC)
155		oldEff := boundary.Add(-1) // 与新版落在同一秒内，仅差一纳秒
156		writeDiskFile(t, dir, diskState{
157			Points: openPoints(),
158			Limits: map[string][]Limit{
159				diskLimitKey("P1", openPH): {
160					// 故意乱序排列，证明排序后按纳秒精度比较。
161					{PointID: "P1", Item: openPH, Value: 5, Effective: boundary},
162					{PointID: "P1", Item: openPH, Value: 10, Effective: oldEff},
163				},
164			},
165			Samples: map[string]*Sample{
166				"S-BEFORE": {
167					ID: "S-BEFORE", PointID: "P1", SampledAt: oldEff,
168					Measurements: []Measurement{{Item: openPH, Value: 7}},
169					Status:       StatusPending,
170				},
171				"S-AT": {
172					ID: "S-AT", PointID: "P1", SampledAt: boundary,
173					Measurements: []Measurement{{Item: openPH, Value: 7}},
174					Status:       StatusPending,
175				},
176			},
177		})
178		s, err := Open(dir)
179		if err != nil {
180			t.Fatalf("相差一纳秒的两版应正常打开: %v", err)
181		}
182		defer s.Close()
183	
184		before, err := s.Confirm("S-BEFORE")
185		if err != nil {
186			t.Fatalf("Confirm S-BEFORE: %v", err)
187		}
188		if r := before.Results[0]; r.Limit != 10 || !r.LimitEffective.Equal(oldEff) || r.Exceeded {
189			t.Fatalf("边界前一纳秒应采用旧版 10 且 7 ≤ 10 达标: %+v", r)
190		}
191		at, err := s.Confirm("S-AT")
192		if err != nil {
193			t.Fatalf("Confirm S-AT: %v", err)
194		}
195		if r := at.Results[0]; r.Limit != 5 || !r.LimitEffective.Equal(boundary) || !r.Exceeded {
196			t.Fatalf("恰好生效应采用新版 5 且 7 > 5 超标: %+v", r)
197		}
198	}
199	
200	// 不同采样点或不同项目在同一时刻各登记一版限值完全合法：文件正常打开，
201	// 确认时各组只用自己的限值。
202	func TestOpenSameEffectiveTimeAcrossDifferentGroupsIsLegal(t *testing.T) {
203		dir := t.TempDir()
204		eff := at(1, 0)
205		writeDiskFile(t, dir, diskState{
206			Points: map[string]SamplingPoint{
207				"P1": {ID: "P1", Name: "一号取水口"},
208				"P2": {ID: "P2", Name: "二号取水口"},
209			},
210			Limits: map[string][]Limit{
211				diskLimitKey("P1", openPH): {
212					{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
213				},
214				diskLimitKey("P2", openPH): {
215					{PointID: "P2", Item: openPH, Value: 6, Effective: eff},
216				},
217				diskLimitKey("P1", "COD"): {
218					{PointID: "P1", Item: "COD", Value: 30, Effective: eff},
219				},
220			},
221			Samples: map[string]*Sample{
222				"S1": {
223					ID: "S1", PointID: "P1", SampledAt: at(2, 0),
224					Measurements: []Measurement{{Item: openPH, Value: 7}},
225					Status:       StatusPending,
226				},
227				"S2": {
228					ID: "S2", PointID: "P2", SampledAt: at(2, 0),
229					Measurements: []Measurement{{Item: openPH, Value: 7}},
230					Status:       StatusPending,
231				},
232			},
233		})
234		s, err := Open(dir)
235		if err != nil {
236			t.Fatalf("不同组在同一时刻登记限值应正常打开: %v", err)
237		}
238		defer s.Close()
239		r1, err := s.Confirm("S1")
240		if err != nil || r1.Results[0].Limit != 8 || r1.Exceeded {
241			t.Fatalf("P1/pH 应用本组的 8、7 ≤ 8 达标: %+v err=%v", r1, err)
242		}
243		r2, err := s.Confirm("S2")
244		if err != nil || r2.Results[0].Limit != 6 || !r2.Exceeded {
245			t.Fatalf("P2/pH 应用本组的 6、7 > 6 超标: %+v err=%v", r2, err)
246		}
247	}
248	
249	// 编号与项目名内部的 U+0000 继续支持：旧版本单字符拼接键会把两个不同组
250	// 放进同一个存储条目，同一时刻各有一版是合法的；但其中一组在同一条目下
251	// 再出现同刻第二版，仍必须按记录自身的归属识别为重复并整次拒绝。
252	func TestOpenDuplicateLimitWithinOldCollidedKey(t *testing.T) {
253		dir := t.TempDir()
254		zeroPoint := "P\x00A"
255		zeroItem := "A\x00B"
256		eff := at(1, 0)
257		// 与 limit_group_test.go 中旧格式相同的碰撞键：两组共用。
258		oldKey := zeroPoint + "\x00" + "B"
259		if oldKey != "P"+"\x00"+zeroItem {
260			t.Fatal("测试前提：两个组合应拼出同一个旧键")
261		}
262	
263		// 先验证只有同刻各一版时沿用兼容行为、正常打开。
264		writeDiskFile(t, dir, diskState{
265			Points: map[string]SamplingPoint{
266				zeroPoint: {ID: zeroPoint, Name: "带零编号"},
267				"P":       {ID: "P", Name: "普通编号"},
268			},
269			Limits: map[string][]Limit{
270				oldKey: {
271					{PointID: zeroPoint, Item: "B", Value: 10, Effective: eff},
272					{PointID: "P", Item: zeroItem, Value: 5, Effective: eff},
273				},
274			},
275		})
276		s, err := Open(dir)
277		if err != nil {
278			t.Fatalf("共用旧键的两个不同组同刻各一版应正常读入: %v", err)
279		}
280		if got := s.limits[limitGroup{pointID: "P", item: zeroItem}]; len(got) != 1 {
281			t.Fatalf("旧键重新分组错误: %+v", got)
282		}
283		if err := s.Close(); err != nil {
284			t.Fatalf("Close: %v", err)
285		}
286	
287		// 同一碰撞条目里给 "P"/zeroItem 再放一条同刻版本：必须识别为该组重复。
288		writeDiskFile(t, dir, diskState{
289			Points: map[string]SamplingPoint{
290				zeroPoint: {ID: zeroPoint, Name: "带零编号"},
291				"P":       {ID: "P", Name: "普通编号"},
292			},
293			Limits: map[string][]Limit{
294				oldKey: {
295					{PointID: zeroPoint, Item: "B", Value: 10, Effective: eff},
296					{PointID: "P", Item: zeroItem, Value: 5, Effective: eff},
297					{PointID: "P", Item: zeroItem, Value: 6, Effective: eff},
298				},
299			},
300		})
301		assertOpenRejectsDuplicateLimit(t, dir, "P", zeroItem, eff)
302	}
303	
304	// 没有重复的多版本数据即使在文件中乱序保存，也照常打开并按生效时刻排序：
305	// 采样于各时刻之间的待判定样品取采样当时已生效的最近一版，边界时刻用新版；
306	// 已确认样品保存的历史判定依据原样保留，不按读入的限值重算。
307	func TestOpenUnorderedMultiVersionLimitsLoadAndConfirm(t *testing.T) {
308		dir := t.TempDir()
309		writeDiskFile(t, dir, diskState{
310			Points: openPoints(),
311			Limits: map[string][]Limit{
312				diskLimitKey("P1", openPH): {
313					// 故意按 10 日、1 日、5 日的乱序排列落盘。
314					{PointID: "P1", Item: openPH, Value: 6, Effective: at(10, 0)},
315					{PointID: "P1", Item: openPH, Value: 10, Effective: at(1, 0)},
316					{PointID: "P1", Item: openPH, Value: 7, Effective: at(5, 0)},
317				},
318			},
319			Samples: map[string]*Sample{
320				// 待判定：9/6 采样，应取 9/5 生效的 7，7 ≤ 7 达标。
321				"SP": {
322					ID: "SP", PointID: "P1", SampledAt: at(6, 0),
323					Measurements: []Measurement{{Item: openPH, Value: 7}},
324					Status:       StatusPending,
325				},
326				// 待判定：恰好 9/10 采样，采用新版 6，7 > 6 超标。
327				"SAT": {
328					ID: "SAT", PointID: "P1", SampledAt: at(10, 0),
329					Measurements: []Measurement{{Item: openPH, Value: 7}},
330					Status:       StatusPending,
331				},
332				// 已确认样品保存的是旧依据 10@9/1、判超标（9 > 10 为假，这里保存
333				// 11 > 10 超标），即使与当前限值重算结果不同也必须原样保留。
334				"SC": {
335					ID: "SC", PointID: "P1", SampledAt: at(2, 0),
336					Measurements: []Measurement{{Item: openPH, Value: 11}},
337					Status:       StatusConfirmed, Exceeded: true,
338					Results: []ItemResult{{
339						Item: openPH, Value: 11, Limit: 10,
340						LimitEffective: at(1, 0), Exceeded: true,
341					}},
342				},
343			},
344		})
345		s, err := Open(dir)
346		if err != nil {
347			t.Fatalf("无重复的乱序多版本数据应正常打开: %v", err)
348		}
349		defer s.Close()
350	
351		sp, err := s.Confirm("SP")
352		if err != nil {
353			t.Fatalf("Confirm SP: %v", err)
354		}
355		if r := sp.Results[0]; r.Limit != 7 || !r.LimitEffective.Equal(at(5, 0)) || r.Exceeded {
356			t.Fatalf("9/6 采样应取 9/5 生效的 7、等于上限达标: %+v", r)
357		}
358		sat, err := s.Confirm("SAT")
359		if err != nil {
360			t.Fatalf("Confirm SAT: %v", err)
361		}
362		if r := sat.Results[0]; r.Limit != 6 || !r.LimitEffective.Equal(at(10, 0)) || !r.Exceeded {
363			t.Fatalf("恰好生效时刻应采用新版 6 并超标: %+v", r)
364		}
365		// 历史结论原样保留：重复确认直接返回已保存依据，不重算。
366		sc, err := s.Confirm("SC")
367		if err != nil {
368			t.Fatalf("Confirm SC: %v", err)
369		}
370		if r := sc.Results[0]; r.Limit != 10 || !r.LimitEffective.Equal(at(1, 0)) ||
371			!r.Exceeded || !sc.Exceeded {
372			t.Fatalf("已确认样品的历史判定依据必须原样保留: %+v", r)
373		}
374	}
375	
376	// 文件里同时存在重复限值组和已确认样品时，仍然整次失败：
377	// 不能先读入样品、把拒绝推迟到确认时，也不重算任何历史依据。
378	func TestOpenDuplicateLimitRejectsEvenWithConfirmedSample(t *testing.T) {
379		dir := t.TempDir()
380		eff := at(1, 0)
381		writeDiskFile(t, dir, diskState{
382			Points: openPoints(),
383			Limits: map[string][]Limit{
384				diskLimitKey("P1", openPH): {
385					{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
386					{PointID: "P1", Item: openPH, Value: 9, Effective: eff},
387				},
388			},
389			Samples: map[string]*Sample{
390				"SC": {
391					ID: "SC", PointID: "P1", SampledAt: at(2, 0),
392					Measurements: []Measurement{{Item: openPH, Value: 9}},
393					Status:       StatusConfirmed, Exceeded: true,
394					Results: []ItemResult{{
395						Item: openPH, Value: 9, Limit: 8,
396						LimitEffective: eff, Exceeded: true,
397					}},
398				},
399			},
400		})
401		assertOpenRejectsDuplicateLimit(t, dir, "P1", openPH, eff)
402	}
403	
404	// 打开因重复限值失败后不留下任何内部状态：把问题组修成唯一版本覆盖写回，
405	// 同一目录即可正常打开，历史样品照常可见。
406	func TestOpenDuplicateLimitRejectionLeavesNoState(t *testing.T) {
407		dir := t.TempDir()
408		eff := at(1, 0)
409		bad := diskState{
410			Points: openPoints(),
411			Limits: map[string][]Limit{
412				diskLimitKey("P1", openPH): {
413					{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
414					{PointID: "P1", Item: openPH, Value: 9, Effective: eff},
415				},
416			},
417			Samples: map[string]*Sample{
418				"SP": {
419					ID: "SP", PointID: "P1", SampledAt: at(2, 0),
420					Measurements: []Measurement{{Item: openPH, Value: 7}},
421					Status:       StatusPending,
422				},
423			},
424		}
425		writeDiskFile(t, dir, bad)
426		if got, err := Open(dir); !errors.Is(err, ErrDuplicateLimitTime) || got != nil {
427			t.Fatalf("重复限值必须拒绝，got=%v err=%v", got, err)
428		}
429		good := bad
430		good.Limits[diskLimitKey("P1", openPH)] = []Limit{
431			{PointID: "P1", Item: openPH, Value: 8, Effective: eff},
432		}
433		writeDiskFile(t, dir, good)
434		s, err := Open(dir)
435		if err != nil {
436			t.Fatalf("修正为唯一版本后应正常打开: %v", err)
437		}
438		defer s.Close()
439		list, err := s.ListByPoint("P1")
440		if err != nil || len(list) != 1 || list[0].ID != "SP" {
441			t.Fatalf("修正后应能看到原有样品: %+v err=%v", list, err)
442		}
443	}
