// 归属核对针对文件中实际存在的每一版：旧版或尚未生效的未来版本归属不明同样
// 拒绝，不能只检查当前会被采用的版本；同组另有归属完整的版本也不能遮住问题。
func TestOpenLimitOldAndFutureVersionsOwnershipChecked(t *testing.T) {
