	if !errors.Is(err, ErrCorruptRecord) {
		t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
	}
	if !strings.Contains(err.Error(), "P9") {
		t.Fatalf("错误信息应带出归属不明的采样点编号 P9，实际 %q", err.Error())
	}
}

